private fun updateRuns(){val container=activeContainer?:return;TimerStore(this).use{store->val runs=store.activeRuns();if(runs.isEmpty()){if(container.childCount>0)render();return@use};container.removeAllViews();runs.forEach{r->val remain=if(r.bootCount>=0&&r.bootCount==TimerScheduler.bootCount(this)&&SystemClock.elapsedRealtime()>=r.startElapsed)r.deadlineElapsed-SystemClock.elapsedRealtime() else r.deadlineWall-System.currentTimeMillis();val seconds=maxOf(0L,remain/1000L);val panel=LinearLayout(this).apply{orientation=LinearLayout.HORIZONTAL;gravity=Gravity.CENTER_VERTICAL;background=shape(surface,Color.RED);setPadding(dp(12),dp(10),dp(9),dp(10))};val info=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL};info.addView(text(r.name,14f,true).apply{maxLines=1;ellipsize=android.text.TextUtils.TruncateAt.END});info.addView(text("${seconds/86400}d ${seconds/3600%24}h ${seconds/60%60}m ${seconds%60}s",21f,true,accent));info.addView(text("${TimeMath.names[r.period]} · ${TimeMath.fraction(r.radix,r.level)}",11f,false,subdued));info.addView(text("@ ${TimeMath.fireTimestamp(r.deadlineWall)} Local",12f,true,accent).apply{setSingleLine(true);setAutoSizeTextTypeUniformWithConfiguration(9,12,1,android.util.TypedValue.COMPLEX_UNIT_SP)});panel.addView(info,LinearLayout.LayoutParams(0,LinearLayout.LayoutParams.WRAP_CONTENT,1f));panel.addView(smallButton("CANCEL"){TimerScheduler.cancel(this,r);store.cancel(r.id);render()},LinearLayout.LayoutParams(dp(70),dp(36)).apply{leftMargin=dp(8)});spaced(container,panel,8)}}}
private fun savePreset(){captureName();try{TimerStore(this).use{it.savePreset(currentPreset())};note("Preset saved");editor=false;nameField=null;render()}catch(ex:Exception){note("Cannot save: ${ex.message}")}}
private fun createRun(p:Preset){if(p.uri.isEmpty()){note("Select an audio file first");return};if(!TimerScheduler.authorized(this)){note("Grant exact-alarm permission first");return};try{val r=TimerStore(this).use{it.createRun(p,System.currentTimeMillis(),SystemClock.elapsedRealtime(),TimerScheduler.bootCount(this))};try{TimerScheduler.arm(this,r);note("Started ${TimeMath.durationLabel(r.durationNs)}");editor=false;nameField=null}catch(ex:Exception){TimerStore(this).use{it.updateRun(r.id,"blocked","Could not arm: ${ex.message}")};note("Alarm could not be scheduled: ${ex.message}")};render()}catch(ex:Exception){note("Cannot start timer: ${ex.message}")}}
private fun chooseFile(){captureName();val i=Intent(Intent.ACTION_OPEN_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType("*/*").addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION or Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION);startActivityForResult(i,REQUEST_FILE)}
private fun displayName(u:Uri):String{var value=u.lastPathSegment?:"selected audio";try{contentResolver.query(u,arrayOf(OpenableColumns.DISPLAY_NAME),null,null,null)?.use{c:Cursor->if(c.moveToFirst())value=c.getString(0)?:value}}catch(_:Exception){};return value}
@Deprecated("Legacy activity result avoids AndroidX")
override fun onActivityResult(request:Int,result:Int,data:Intent?){super.onActivityResult(request,result,data);if(request!=REQUEST_FILE||result!=RESULT_OK)return;val u=data?.data?:return;try{contentResolver.takePersistableUriPermission(u,Intent.FLAG_GRANT_READ_URI_PERMISSION)}catch(_:Exception){};val fileName=displayName(u);note("Checking audio compatibility…");Thread{val problem=try{if(fileName.lowercase(Locale.ROOT).endsWith(".wv")){contentResolver.openFileDescriptor(u,"r")?.use{pfd->val h=WavPackNative.nativeOpen(pfd.fd);try{val details=WavPackNative.nativeInfo(h)?:throw Exception("Invalid WavPack file");if(details.size<3||details[0] !in 8000..192000||details[1] !in 1..2)throw Exception("Unsupported WavPack audio")}finally{WavPackNative.nativeClose(h)}}?:throw Exception("File unavailable")}else{val p=android.media.MediaPlayer();try{p.setDataSource(this,u);p.prepare()}finally{p.release()}};null}catch(ex:Throwable){ex.message?:"File cannot be decoded"};runOnUiThread{if(problem==null){uri=u.toString();file=fileName;note("Audio selected: $fileName")}else note("Unsupported or inaccessible audio: $problem");if(editor)render()}}.start()}
}
